from pathlib import Path
import json,collections
R=Path('06_resultados'); rows=json.loads((R/'soporte/fragmentos.json').read_text(encoding='utf-8')); by={x['ref']:x for x in rows}
def refs(s):
 out=[]
 for group in s.split(';'):
  e,nums=group.strip().split(':')
  for n in nums.split(','):
   if '-' in n:
    a,b=map(int,n.split('-')); out += [f'E{int(e):02}-F{i:02}' for i in range(a,b+1)]
   else: out.append(f'E{int(e):02}-F{int(n):02}')
 assert all(x in by for x in out); return out
spec=[
('A1','Suficiencia percibida y escala del registro','3:1-3,6-7;4:1,3,4,8;5:1-5;8:1-2;9:1-2;12:3-4;13:1-2,4-8;15:1-5;16:5-6','El bajo volumen, el trabajo individual y el hábito justifican prácticas vigentes según los participantes. No equivalen a integridad auditada.','Cierre, atención individual y negocio de baja escala.','Cuaderno, cálculo mental, traspaso a computadora o sistema ya instalado.','Varios no expresan necesidad de sustituir su método; E13 usa metas y E15 valora software.','Suficiencia percibida es una condición de adopción; no causa demostrada de pérdida.',['E03-F02','E13-F06','E16-F06']),
('A2','Registro compatible con la atención','1:3;3:3,6-7;10:2,4-7,9-10;13:4-5','E10 atribuye omisiones a afluencia, demora al enfoque de cámara y abandono a calidad de atención. E03/E13 anticipan sobrecarga; no han demostrado esa falla en una prueba.','Registro durante venta y cierre posterior.','E10 deja celular y planea computadora/lector; E03 organiza precios; E13 mantiene cuaderno.','Omisiones y abandono autorreportados en E10. E01 estima 30–45 minutos de cierre, sin demostrar causa común.','Síntomas: ventas omitidas y demora. Causa candidata: interacción de captura y presión de atención; observación pendiente.',['E10-F02','E10-F07','E10-F10']),
('A3','Capacidades y coordinación de quienes atienden','1:7;2:1;6:5-6;8:5-7;13:6;16:9','E01 vincula freno a habilidad de una persona mayor; E16 concentra QR en hijo; E08 señala dificultad y señal.','Turnos familiares y equipos con varios operadores.','Posponen sistema, concentran tareas o consultan ventas del personal.','La disponibilidad del usuario hábil condiciona la operación; ausencia de hijo y efecto en ventas no investigados.','Posibles causas de adopción incompleta; edad por sí sola no explica habilidad.',['E01-F07','E06-F06','E16-F09']),
('A4','Adecuación y continuidad del software','1:6;2:2-3,5-7;5:5;6:2-3,7;7:5-6;10:8-10;14:2-4;15:3-5','Se relatan falta de adaptación, continuidad y capacidad. E07 descarta precio, con motivo de conteo poco claro.','Selección, uso, carga y sustitución de herramientas.','Contratan desarrollo (E02), intentan contactar desarrollador (E14), pagan instalación (E06) o mensualidad (E15).','Costos reales declarados y búsqueda de alternativas coexisten con satisfacción E15. No prueba que Qhatu capture esa demanda.','Síntomas de limitaciones técnicas y ajuste; causas concretas necesitan inspección del flujo.',['E02-F05','E06-F07','E15-F04']),
('A5','Decisiones de inventario y perecederos','4:6-7;6:6;7:3,6-8;9:4-5;10:11-12;11:2-3,7,9-10;14:1,5,7;16:1-4,7','E10 relata demanda variable frente a vida útil; E16 no controla fechas; E14 necesita adecuación a flores. E09 aporta sobrecompra estacional histórica.','Recepción, reposición, consulta de precios y revisión de documentos.','Reponen a ojo, ajustan compras por experiencia, usan sistemas o conservan facturas.','Stock inmovilizado relatado, dificultad de fechas y memoria; pérdida por vencimiento no cuantificada. E04 presenta dolor documental distinto.','Vencimiento o faltante son síntomas; seguimiento insuficiente es candidato junto con demanda variable.',['E10-F12','E11-F09','E16-F04']),
('A6','Políticas de crédito y exposición al impago','1:4-5;2:4;3:4-5;4:5;5:3;6:4;8:3-4;10:3-4;11:11-12;15:6;16:8','E03/E11 relacionan impago pasado con restricción. E01 otorga crédito a empresas.','Crédito empresarial, conocidos, excepciones y garantías.','Rechazan o restringen fiado; clientes recuerdan consumos a E10.','Se reportan impagos pasados en E01/E03/E11; no hay monto mensual y fecha reciente verificables.','No pago puede depender del deudor, no solo del registro. Olvido en E10 es mecanismo diferente.',['E03-F04','E11-F11','E10-F04']),
('A7','Confirmación y confianza en pagos QR','8:8-9;15:7-8;16:9','E08 sospecha comprobantes y espera abono; E15 atribuye espera a internet del cliente o banco; E16 reporta habilidad familiar.','Momento del cobro y entrega.','Esperan confirmación o delegan al hijo.','Fila detenida E15, vigilancia E08 y dependencia E16; fraude consumado no demostrado.','Causas distintas: verificación, infraestructura y habilidades; no se suman como mismo fallo.',['E08-F09','E15-F08','E16-F09']),
('A8','Presión económica y continuidad del negocio','4:2;7:2,7;9:3-8;11:3-5,8,13;12:1-5;14:8-9','Los participantes atribuyen dificultad a bajas ventas, costos, bloqueos y riesgo; no es verificación macroeconómica.','Sostenimiento del negocio, compras y horarios.','Ajustan surtido, diversifican, reducen consumo, extienden horario o reciben apoyo.','E09 apenas paga alquiler; E12 describe actividad mínima; E14 limita compromisos futuros.','Problemas relevantes que no se explican por falta de app. Causalidad externa relatada, no validada.',['E09-F08','E12-F03','E14-F08'])]
cats=[]; parts=['# Codificación axial de Qhatu\n\n25 de noviembre de 2026. Se revisaron 130 fragmentos de 16 entrevistas. Categorías interpretativas con causas candidatas explícitas. Los códigos pueden pertenecer a más de una categoría.\n']
for id,name,ss,cause,context,act,cons,sym,qs in spec:
 rr=refs(ss); cats.append(dict(id=id,nombre=name,refs=rr)); cc=collections.Counter(by[x]['codigo'] for x in rr)
 parts.append(f'## {id} Categoría {name}\n\n**Códigos incluidos:** '+ '; '.join(f'{c} ({n})' for c,n in cc.items())+'.\n\n**Referencias:** '+', '.join(rr)+'.\n\n**Entrevistas donde aparece:** '+', '.join(sorted({by[x]['entrevista'] for x in rr}))+f'.\n\n**Condiciones causales:** {cause}\n\n**Contexto:** {context}\n\n**Estrategias y acciones:** {act}\n\n**Consecuencias:** {cons}\n\n**¿Síntoma o causa?:** {sym}\n\n**Citas representativas:**\n\n'+'\n\n'.join(f'“{by[q]["cita"]}” ({q}).' for q in qs))
parts.append('''\n## Mapa de relaciones entre categorías

- A1 modera el incentivo a adoptar A4: que exista software no significa que sustituir el hábito aporte valor (E05, E13, E15).
- A2 puede bloquear el beneficio de A5: una app con alertas útiles se abandona si dificulta la atención (E10).
- A3 condiciona continuidad de A2/A4: basta que un operador no pueda usar el sistema para que el equipo posponga adopción (E01).
- A4 puede apoyar A5 (E06) o dejar necesidades sin cubrir (E14). Son casos diferentes, no una relación universal.
- A6 y A7 usan confianza y restricción para reducir riesgo, pero impago de crédito y comprobante QR son fenómenos distintos.
- A8 cambia el valor percibido de A1 y A5: baja rotación lleva a abandonar registro (E09), mientras E11 quiere evitar capital inmovilizado.

Las flechas conceptuales son hipótesis explicativas; no hay diseño causal ni observación longitudinal.
''')
(R/'02_codificacion_axial.md').write_text('\n'.join(parts),encoding='utf-8')
(R/'soporte/categorias.json').write_text(json.dumps(cats,ensure_ascii=False,indent=2),encoding='utf-8')
# Actualizar alcance, preservando hipótesis originales.
p=Path('01_contexto/01_contexto_startup.md'); s=p.read_text(encoding='utf-8'); start=s.index('**Trabajo previo declarado:**'); end=s.index('**Meta declarada:**'); s=s[:start]+'**Corpus actualizado al 25 de noviembre de 2026:** 16 transcripciones E01–E16. Las antiguas E01/E02 corresponden a E15/E16. E01–E14 son los nuevos archivos aportados. El taller menciona cinco entrevistas iniciales, sin correspondencia comprobada: no se agregan al denominador. Se incluye una florería como segmento adyacente.\n'+s[end:]; p.write_text(s,encoding='utf-8')
p=Path('01_contexto/04_hipotesis_equipo.md'); s=p.read_text(encoding='utf-8').replace('Ningún umbral se da por alcanzado con dos entrevistas ni se recalcula sobre dos.','Los umbrales originales se conservan. Hay 16 entrevistas heterogéneas; no se recalculan automáticamente sobre 16 ni se equiparan preguntas no realizadas con respuestas negativas. No hay piloto ni preventas documentadas.'); p.write_text(s,encoding='utf-8')
